{"content": "#!/usr/bin/env python3
"""
Factory Lane Pipeline Worker

This worker monitors tasks for a specific pipeline stage (builder/sandbox/flowforce/infra)
and processes them. Upon completion, it creates a task for the next stage.
"""

import requests
import time
import sys
import json

API_BASE = "http://localhost:8000"
STAGE = sys.argv[1] if len(sys.argv) > 1 else "builder"
API_KEY = sys.argv[2] if len(sys.argv) > 2 else "key_a317daac63ea5831"

headers = {
    "X-API-Key": API_KEY,
    "Content-Type": "application/json"
}

# Stage mapping
NEXT_STAGE = {
    "builder": "sandbox",
    "sandbox": "flowforce",
    "flowforce": "infra",
    "infra": None  # Final stage
}

def get_tasks_for_stage():
    """Get pending tasks for this stage."""
    resp = requests.get(
        f"{API_BASE}/tasks",
        headers=headers,
        params={"tags": STAGE, "status": "pending", "limit": 5}
    )
    if resp.status_code == 200:
        return resp.json().get("tasks", [])
    else:
        print(f"❌ Error getting tasks: {resp.text}")
        return []

def complete_task(task_id, result=None, error=None):
    """Complete a task."""
    payload = {}
    if result:
        payload["result"] = result
    if error:
        payload["error"] = error

    resp = requests.post(
        f"{API_BASE}/tasks/{task_id}/complete",
        headers=headers,
        json=payload
    )
    return resp.status_code == 200

def create_next_stage_task(current_task, next_stage):
    """Create a task for the next stage."""
    payload = {
        "task_type": "pipeline",
        "description": f"[Pipeline] {next_stage.upper()}: {current_task['description']}",
        "input_data": current_task.get("input_data", {}),
        "priority": "normal",
        "tags": [next_stage],
        "metadata": {
            "pipeline": "factory_lane",
            "stage": next_stage,
            "previous_stage": STAGE,
            "previous_task_id": current_task["task_id"]
        }
    }

    resp = requests.post(
        f"{API_BASE}/tasks",
        headers=headers,
        json=payload
    )
    if resp.status_code == 200:
        print(f"  ✅ Created {next_stage} task: {resp.json().get('task_id')}")
        return True
    else:
        print(f"  ❌ Failed to create {next_stage} task: {resp.text}")
        return False

def process_task(task):
    """Process a pipeline task."""
    print(f"\n📦 Processing task {task['task_id']}")
    print(f"   Description: {task['description']}")
    print(f"   Input: {task.get('input_data', {})}")

    # Simulate processing based on stage
    if STAGE == "builder":
        print("  🔨 Building...")
        time.sleep(1)
        result = {"status": "built", "build_id": task["task_id"]}

    elif STAGE == "sandbox":
        print("  🧪 Running tests in sandbox...")
        time.sleep(2)
        # Simulate test result
        result = {"status": "tested", "passed": True, "sandbox_id": task["task_id"]}

    elif STAGE == "flowforce":
        print("  🚀 Preparing deployment...")
        time.sleep(1)
        result = {"status": "ready", "deployment_id": task["task_id"]}

    elif STAGE == "infra":
        print("  🏗️ Deploying to production...")
        time.sleep(1)
        result = {"status": "deployed", "production": True}

    # Complete current task
    if complete_task(task["task_id"], result=result):
        print(f"  ✅ Task completed")
    else:
        print(f"  ❌ Failed to complete task")
        return

    # Create next stage task
    next_stage = NEXT_STAGE.get(STAGE)
    if next_stage:
        create_next_stage_task(task, next_stage)
    else:
        print("  🎉 Pipeline complete! (Final stage)")

def main():
    print(f"🏭 Factory Lane Pipeline Worker - Stage: {STAGE.upper()}")
    print(f"Monitoring tags: {STAGE}")
    print("="*50)

    while True:
        tasks = get_tasks_for_stage()

        if tasks:
            print(f"\n📋 Found {len(tasks)} task(s)")
            for task in tasks:
                process_task(task)
        else:
            sys.stdout.write(".")
            sys.stdout.flush()

        time.sleep(5)  # Poll every 5 seconds

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\n\n👋 Worker stopped")
